-- A version string is never reused for different content:
DO $$ BEGIN
  IF (SELECT checksum FROM offering_catalogue_versions WHERE version = 'registration-1.0-draft') <> 'fb0db83e55beb8d8b57588cea9676a3466aa5867690454d850e814811669ab69' THEN
